      "ChatLambda": {
        "Type": "AWS::Lambda::Function",
        "Properties": {
          "FunctionName": "RestaurantAgent-Chat",
          "Runtime": "python3.13",
          "Handler": "index.handler",
          "Role": {
            "Fn::GetAtt": [
              "ChatLambdaRole",
              "Arn"
            ]
          },
          "Timeout": 300,
          "MemorySize": 512,
          "ReservedConcurrentExecutions": 10,
