import boto3
import os
from decimal import Decimal

dynamodb = boto3.resource('dynamodb')

def decimal_default(obj):
    if isinstance(obj, Decimal):
        return float(obj)
    raise TypeError

def lambda_handler(event, context):
    try:
        path = event.get('path', '')
        method = event.get('httpMethod', 'GET')

        # Security headers
        headers = {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Headers': 'Content-Type,X-Amz-Date,Authorization,X-Api-Key,X-Amz-Security-Token',
            'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
            'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
            'X-Content-Type-Options': 'nosniff',
            'X-Frame-Options': 'DENY',
            'X-XSS-Protection': '1; mode=block'
        }

        if method == 'OPTIONS':
            return {
                'statusCode': 200,
                'headers': headers,
                'body': ''
            }

        # Input validation
        if not path or len(path) > 100:
            return {
                'statusCode': 400,
                'headers': headers,
                'body': json.dumps({'error': 'Invalid path'})
            }

        if path == '/restaurants':
            table = dynamodb.Table(os.environ['RESTAURANTS_TABLE'])
            response = table.scan()
            return {
                'statusCode': 200,
                'headers': headers,
                'body': json.dumps(response['Items'], default=decimal_default)
            }

        elif path == '/tickets':
            table = dynamodb.Table(os.environ['TICKETS_TABLE'])
            response = table.scan()
            return {
                'statusCode': 200,
                'headers': headers,
                'body': json.dumps(response['Items'], default=decimal_default)
            }

        elif path == '/equipment':
            table = dynamodb.Table(os.environ['EQUIPMENT_TABLE'])
            response = table.scan()
            return {
                'statusCode': 200,
                'headers': headers,
                'body': json.dumps(response['Items'], default=decimal_default)
            }

        elif path == '/inventory':
            table = dynamodb.Table(os.environ['INVENTORY_TABLE'])
            response = table.scan()
            return {
                'statusCode': 200,
                'headers': headers,
                'body': json.dumps({'inventory': response['Items']}, default=decimal_default)
            }

        elif path == '/staffing':
            table = dynamodb.Table(os.environ['STAFFING_TABLE'])
            response = table.scan()
            return {
                'statusCode': 200,
                'headers': headers,
                'body': json.dumps({'staffing': response['Items']}, default=decimal_default)
            }

        elif path == '/voice-token':
            from urllib.parse import quote as url_quote
            from botocore.auth import SigV4QueryAuth
            from botocore.awsrequest import AWSRequest
            from botocore.session import Session as BotoSession

            agent_arn = os.environ.get('AGENT_RUNTIME_ARN', '')
            if not agent_arn:
                return {'statusCode': 500, 'headers': headers, 'body': json.dumps({'error': 'AGENT_RUNTIME_ARN not set'})}

            rgn = os.environ.get('AWS_REGION', 'us-east-1')
            host = f'bedrock-agentcore.{rgn}.amazonaws.com'
            encoded_arn = url_quote(agent_arn, safe='')
            url = f'https://{host}/runtimes/{encoded_arn}/ws'

            bsession = BotoSession()
            creds = bsession.get_credentials().get_frozen_credentials()
            request = AWSRequest(method='GET', url=url, headers={'host': host})
            signer = SigV4QueryAuth(creds, 'bedrock-agentcore', rgn, expires=300)
            signer.add_auth(request)
            ws_url = request.url.replace('https://', 'wss://')

            return {
                'statusCode': 200,
                'headers': headers,
                'body': json.dumps({'wsUrl': ws_url})
            }

        return {
            'statusCode': 404,
            'headers': headers,
            'body': json.dumps({'error': 'Not found'})
        }

    except Exception as e:
        return {
            'statusCode': 500,
            'headers': headers,
            'body': json.dumps({'error': 'Internal server error'})
        }
